package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.AnnotatedWithParams;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.type.TypeBindings;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_verifyNonDup_TriageGen0Test {

    private CreatorCollector collector;
    private BeanDescription beanDesc;
    private AnnotatedWithParams mockNewOne;
    private AnnotatedWithParams mockOldOne;

    // Accessing protected field via reflection for testing purposes
    // as the class doesn't provide direct setters for the internal array state
    private static final String CREATORS_FIELD = "_creators";
    private static final String EXPLICIT_CREATORS_FIELD = "_explicitCreators";
    private static final String HAS_NON_DEFAULT_CREATOR_FIELD = "_hasNonDefaultCreator";

    @Before
    public void setUp() throws Exception {
        beanDesc = mock(BeanDescription.class);
        collector = new CreatorCollector(beanDesc, true);
        mockNewOne = mock(AnnotatedWithParams.class);
        mockOldOne = mock(AnnotatedWithParams.class);

        // Ensure mockNewOne returns a specific class to test the class equality logic
        // We use a real subclass or a mock that returns a specific class
        when(mockNewOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(mockOldOne.getClass()).thenReturn(AnnotatedWithParams.class);
    }

    /**
     * Helper to set private fields in CreatorCollector for state manipulation
     */
    private void setInternalState(String fieldName, Object value) throws Exception {
        Field field = CreatorCollector.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(collector, value);
    }

    /**
     * Helper to get private fields from CreatorCollector
     */
    private Object getInternalState(String fieldName) throws Exception {
        Field field = CreatorCollector.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(collector);
    }

    @Test
    public void testVerifyNonDup_NewOneIsFirst() throws Exception {
        int typeIndex = 0;

        // Ensure array is initialized
        AnnotatedWithParams[] creators = new AnnotatedWithParams[5];
        setInternalState(CREATORS_FIELD, creators);

        // Invoke protected method via reflection or subclass
        invokeVerifyNonDup(mockNewOne, typeIndex, true);

        assertTrue("Should set hasNonDefaultCreator to true", (Boolean) getInternalState(HAS_NON_DEFAULT_CREATOR_FIELD));
        assertEquals(mockNewOne, creators[typeIndex]);
    }

    @Test
    public void testVerifyNonDup_AlreadyHasExplicit_NewNotExplicit_Skips() throws Exception {
        int typeIndex = 1;
        AnnotatedWithParams[] creators = new AnnotatedWithParams[5];
        creators[typeIndex] = mockOldOne;
        setInternalState(CREATORS_FIELD, creators);
        setInternalState(EXPLICIT_CREATORS_FIELD, 1 << typeIndex);

        // If old is explicit and new is not, it should return early (skip)
        invokeVerifyNonDup(mockNewOne, typeIndex, false);

        assertEquals(mockOldOne, creators[typeIndex]);
        assertFalse("Should not have updated creator", creators[typeIndex] == mockNewOne);
    }

    @Test
    public void testVerifyNonDup_AlreadyHasExplicit_NewIsExplicit_ProceedsToConflictCheck() throws Exception {
        int typeIndex = 0;
        AnnotatedWithParams[] creators = new AnnotatedWithParams[5];
        creators[typeIndex] = mockOldOne;
        setInternalState(CREATORS_FIELD, creators);
        setInternalState(EXPLICIT_CREATORS_FIELD, 1 << typeIndex);

        // Both explicit: if classes match, throws exception. 
        // We override mockNewOne class to be different to avoid exception and check update
        AnnotatedWithParams differentClassNewOne = mock(AnnotatedWithParams.class);
        // The logic: if (oldOne.getClass() == newOne.getClass()) 
        // We ensure they are different to test the "otherwise" path
        when(mockOldOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(differentClassNewOne.getClass()).thenReturn(Object.class);

        invokeVerifyNonDup(differentClassNewOne, typeIndex, true);

        assertEquals(differentClassNewOne, creators[typeIndex]);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testVerifyNonDup_ConflictSameClass_ThrowsException() throws Exception {
        int typeIndex = 0;
        AnnotatedWithParams[] creators = new AnnotatedWithParams[5];
        creators[typeIndex] = mockOldOne;
        setInternalState(CREATORS_FIELD, creators);

        // Ensure classes are identical to trigger the exception
        when(mockOldOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(mockNewOne.getClass()).thenReturn(AnnotatedWithParams.class);

        invokeVerifyNonDup(mockNewOne, typeIndex, true);
    }

    @Test
    public void testVerifyNonDup_OverrideExplicitBit() throws Exception {
        int typeIndex = 2;
        AnnotatedWithParams[] creators = new AnnotatedWithParams[5];
        creators[typeIndex] = mockOldOne;
        setInternalState(CREATORS_FIELD, creators);
        setInternalState(EXPLICIT_CREATORS_FIELD, 0);

        // Different classes to avoid exception
        when(mockOldOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(mockNewOne.getClass()).thenReturn(Object.class);

        invokeVerifyNonDup(mockNewOne, typeIndex, true);

        int mask = (1 << typeIndex);
        int explicitCreators = (int) getInternalState(EXPLICIT_CREATORS_FIELD);
        assertEquals("Explicit bit should be set", mask, explicitCreators & mask);
        assertEquals(mockNewOne, creators[typeIndex]);
    }

    @Test
    public void testVerifyNonDup_NotExplicit_DoesNotSetBit() throws Exception {
        int typeIndex = 0;
        AnnotatedWithParams[] creators = new AnnotatedWithParams[5];
        creators[typeIndex] = mockOldOne;
        setInternalState(CREATORS_FIELD, creators);
        setInternalState(EXPLICIT_CREATORS_FIELD, 0);

        when(mockOldOne.getClass()).thenReturn(AnnotatedWithParams.class);
        when(mockNewOne.getClass()).thenReturn(Object.class);

        invokeVerifyNonDup(mockNewOne, typeIndex, false);

        int explicitCreators = (int) getInternalState(EXPLICIT_CREATORS_FIELD);
        assertEquals("Explicit bit should NOT be set", 0, explicitCreators);
    }

    /**
     * Helper to invoke the protected method via reflection
     */
    private void invokeVerifyNonDup(AnnotatedWithParams newOne, int typeIndex, boolean explicit) throws Exception {
        java.lang.reflect.Method method = CreatorCollector.class.getDeclaredMethod(
                "verifyNonDup", AnnotatedWithParams.class, int.class, boolean.class);
        method.setAccessible(true);
        method.invoke(collector, newOne, typeIndex, explicit);
    }
}
